def rates(fit_df, column, smoothing, prior_rate):
    g = fit_df.groupby(column)["liked"].agg(["size", "sum"])
    return (g["sum"] + smoothing * prior_rate) / (g["size"] + smoothing)


def add(df, occupation_rates, age_rates, region_rates, prior_rate):
    out = df.copy()
    out["f_occupation_rate"] = out["f_occupation"].map(occupation_rates).fillna(prior_rate).values
    out["f_age_band_rate"] = out["f_age_band"].map(age_rates).fillna(prior_rate).values
    out["f_region_rate"] = out["f_region"].map(region_rates).fillna(prior_rate).values
    return out
